def amicable_numbers_sum(n):
    if n < 1:
        return 0

    # Sum of proper divisors for every number from 0 to n (sieve approach).
    div_sum = [0] * (n + 1)
    for i in range(1, n // 2 + 1):
        for j in range(2 * i, n + 1, i):
            div_sum[j] += i

    def proper_divisor_sum(x):
        if x < 2:
            return 0
        total = 1
        r = int(x ** 0.5)
        for k in range(2, r + 1):
            if x % k == 0:
                total += k
                other = x // k
                if other != k:
                    total += other
        return total

    total = 0
    for num in range(2, n + 1):
        partner = div_sum[num]
        if partner > 0 and partner != num:
            if partner <= n:
                if div_sum[partner] == num:
                    total += num
            elif proper_divisor_sum(partner) == num:
                total += num
    return total
```

