def count_Primes_nums(n):
    """Return the number of prime numbers strictly less than n."""
    if n <= 2:
        return 0
    # Sieve of Eratosthenes over numbers 0..n-1 (bytearray for memory efficiency)
    sieve = bytearray([1]) * n
    sieve[0] = 0
    sieve[1] = 0
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i::i] = bytearray(len(sieve[i * i::i]))
    return sum(sieve)
