def sequential_search(arr, element):
    """
    Sequentially search for `element` in `arr`.

    Args:
        arr: The array (list) to search through.
        element: The value to look for.

    Returns:
        A tuple (found, index) where:
            found is True and index is the position of the first
                occurrence of `element` if it is present;
            found is False and index is -1 if `element` is not present.
    """
    for index, value in enumerate(arr):
        if value == element:
            return (True, index)
    return (False, -1)
```

