def check_distinct(t):
    """
    Check whether the given tuple contains no duplicate elements.

    Returns True if all elements are distinct, False otherwise.
    Handles both hashable and unhashable elements.
    """
    try:
        # Fast path for hashable items
        return len(set(t)) == len(t)
    except TypeError:
        # Fallback for unhashable items (e.g., lists, dicts inside the tuple)
        seen = []
        for item in t:
            if item in seen:
                return False
            seen.append(item)
        return True
```

