def tuple_to_dict(tup):
    """
    Convert a tuple into a dictionary using adjacent elements as
    key-value pairs: elements at even indices (0, 2, 4, ...) become
    keys and the elements immediately following them (odd indices)
    become values.

    Edge cases:
      - Empty tuple      -> returns {} (both slices are empty).
      - Odd-length tuple -> the trailing unpaired element is ignored,
                            because zip() stops at the shorter slice.
      - Duplicate keys   -> the later pair overwrites the earlier one
                            (standard dict behavior).

    Algorithm:
      1. tup[::2]  collects elements at indices 0, 2, 4, ... (keys).
      2. tup[1::2] collects elements at indices 1, 3, 5, ... (values).
      3. zip() pairs them adjacently and dict() builds the result.

    Examples:
        tuple_to_dict((1, 5, 7, 10, 13, 5)) -> {1: 5, 7: 10, 13: 5}
        tuple_to_dict(())                   -> {}
        tuple_to_dict((1, 2, 3))            -> {1: 2}
    """
    return dict(zip(tup[::2], tup[1::2]))


if __name__ == "__main__":
    assert tuple_to_dict((1, 5, 7, 10, 13, 5)) == {1: 5, 7: 10, 13: 5}
    assert tuple_to_dict(()) == {}
    assert tuple_to_dict((1, 2, 3)) == {1: 2}
    assert tuple_to_dict(("a", 1, "b", 2)) == {"a": 1, "b": 2}
    assert tuple_to_dict((1, 2, 1, 3)) == {1: 3}  # duplicate key overwritten
    print("All tests passed.")
